package netsrc

type Net struct {
	Par map[string]string
	Sz  map[string]int
}

func NewNet() *Net {
	return &Net{Par: map[string]string{}, Sz: map[string]int{}}
}

func (n *Net) Add(k string) {
	if _, ok := n.Par[k]; ok {
		return
	}
	n.Par[k] = k
	n.Sz[k] = 1
}

func (n *Net) Find(k string) string {
	n.Add(k)
	root := k
	for n.Par[root] != root {
		root = n.Par[root]
	}
	for n.Par[k] != k {
		next := n.Par[k]
		n.Par[k] = root
		k = next
	}
	return root
}

// Join keeps the lexicographically least token as the component root. Go
// string ordering is byte ordering, which is the required raw UTF-8 order.
func (n *Net) Join(a, b string) {
	ra, rb := n.Find(a), n.Find(b)
	if ra == rb {
		return
	}
	if rb < ra {
		ra, rb = rb, ra
	}
	n.Par[rb] = ra
	n.Sz[ra] += n.Sz[rb]
	delete(n.Sz, rb)
}

func OpTie(toks []string) *Net {
	n := NewNet()
	for _, t := range toks {
		n.Add(t)
	}
	return n
}

func OpMark(n *Net, tok string) string {
	return n.Find(tok)
}
