		left, right, origin := "", "", ""
		for _, raw := range strings.Split(string(body), "\n") {
			line := strings.TrimSpace(raw)
			if line == "" {
				continue
			}
			k, v, ok := strings.Cut(line, "=")
			if !ok {
				return fmt.Errorf("%s: malformed pair line", ent.Name())
			}
			switch strings.TrimSpace(k) {
			case "left":
				left = strings.TrimSpace(v)
			case "right":
				right = strings.TrimSpace(v)
			case "origin":
				origin = strings.TrimSpace(v)
			}
		}
		if origin == "scrapped" {
			return fmt.Errorf("%s: scrapped origin", ent.Name())
		}
		if left == "" || right == "" || origin == "" {
			return fmt.Errorf("%s: incomplete pair", ent.Name())
		}
		n.Join(left, right)
	}
	return nil
}
