package readcue

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

type Rec struct {
	Id  string
	Tok string
}

func Scan(path string) ([]Rec, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	var out []Rec
	s := bufio.NewScanner(f)
	lineNo := 0
	for s.Scan() {
		lineNo++
		line := strings.TrimSuffix(s.Text(), "\r")
		if line == "" {
			continue
		}
		id, tok, ok := strings.Cut(line, " ")
		if !ok || id == "" || tok == "" || strings.Contains(tok, " ") || strings.ContainsAny(id+tok, "\t\r\n") {
			return nil, fmt.Errorf("%s:%d: malformed yarn line", path, lineNo)
		}
		out = append(out, Rec{Id: id, Tok: tok})
	}
	if err := s.Err(); err != nil {
		return nil, err
	}
	return out, nil
}
